CREATE TABLE insights_account(account_id UUID PRIMARY KEY,analytics BOOLEAN NOT NULL DEFAULT false,experiments BOOLEAN NOT NULL DEFAULT false,analytics_since TIMESTAMPTZ,experiments_since TIMESTAMPTZ,version BIGINT NOT NULL DEFAULT 1,next_event_version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE telemetry_receipt(event_id UUID PRIMARY KEY,fingerprint CHAR(64) NOT NULL,received_at TIMESTAMPTZ NOT NULL);
CREATE TABLE telemetry_event(id UUID PRIMARY KEY,account_id UUID NOT NULL REFERENCES insights_account(account_id),profile_id UUID,device_id UUID,session_id UUID,sample_sequence BIGINT,kind VARCHAR(40) NOT NULL,source_trust VARCHAR(8) NOT NULL CHECK(source_trust IN('CLIENT','OWNER')),occurred_at TIMESTAMPTZ NOT NULL,startup_ms BIGINT NOT NULL DEFAULT 0 CHECK(startup_ms BETWEEN 0 AND 120000),buffer_ms BIGINT NOT NULL DEFAULT 0 CHECK(buffer_ms>=0),played_ms BIGINT NOT NULL DEFAULT 0 CHECK(played_ms BETWEEN 0 AND 60000),bitrate_kbps BIGINT NOT NULL DEFAULT 0 CHECK(bitrate_kbps BETWEEN 0 AND 200000),region_hint VARCHAR(8) NOT NULL,device_family VARCHAR(12) NOT NULL,cdn VARCHAR(16) NOT NULL,resolution VARCHAR(8) NOT NULL,failure_code VARCHAR(32) NOT NULL,fingerprint CHAR(64) NOT NULL,UNIQUE(session_id,sample_sequence),CHECK(buffer_ms<=played_ms));
CREATE INDEX telemetry_account_time ON telemetry_event(account_id,occurred_at,id);
CREATE INDEX telemetry_time ON telemetry_event(occurred_at,id);
CREATE TABLE telemetry_owner_cause(kind VARCHAR(40) NOT NULL,cause VARCHAR(160) NOT NULL,account_id UUID NOT NULL REFERENCES insights_account(account_id),occurred_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(kind,cause));
CREATE INDEX telemetry_cause_time ON telemetry_owner_cause(occurred_at);
CREATE INDEX telemetry_receipt_time ON telemetry_receipt(received_at,event_id);
CREATE TABLE telemetry_daily_quota(account_id UUID NOT NULL REFERENCES insights_account(account_id),day DATE NOT NULL,count INTEGER NOT NULL CHECK(count BETWEEN 0 AND 10000),PRIMARY KEY(account_id,day));
CREATE TABLE experiment(id UUID PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,feature VARCHAR(40) NOT NULL CHECK(feature IN('HOME_RAILS','SEARCH_PRESENTATION','AD_PRESENTATION')),enabled BOOLEAN NOT NULL DEFAULT true,starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ NOT NULL CHECK(ends_at>starts_at),control INTEGER NOT NULL CHECK(control BETWEEN 0 AND 100),variant_a INTEGER NOT NULL CHECK(variant_a BETWEEN 0 AND 100),variant_b INTEGER NOT NULL CHECK(variant_b BETWEEN 0 AND 100),version BIGINT NOT NULL DEFAULT 1,CHECK(control+variant_a+variant_b=100));
CREATE TABLE experiment_assignment(account_id UUID NOT NULL REFERENCES insights_account(account_id),experiment_id UUID NOT NULL REFERENCES experiment(id),version BIGINT NOT NULL,variant VARCHAR(12) NOT NULL CHECK(variant IN('CONTROL','VARIANT_A','VARIANT_B')),PRIMARY KEY(account_id,experiment_id,version));
CREATE TABLE insights_audit(id UUID PRIMARY KEY,experiment_id UUID NOT NULL REFERENCES experiment(id),actor_hash CHAR(64) NOT NULL,action VARCHAR(40) NOT NULL,version BIGINT NOT NULL,at TIMESTAMPTZ NOT NULL);
CREATE TABLE outbox_event(event_id UUID PRIMARY KEY,aggregate_id UUID NOT NULL,aggregate_version BIGINT NOT NULL,topic VARCHAR(120) NOT NULL,payload JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,published_at TIMESTAMPTZ,claim_token UUID,claimed_until TIMESTAMPTZ,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,attempts INTEGER NOT NULL DEFAULT 0);
CREATE INDEX insights_outbox_pending_idx ON outbox_event(next_attempt_at,created_at,event_id) WHERE published_at IS NULL;
